const SPELL = { id: "fear", name: "Fear", manaCost: 6, range: 8, script: "fear" };

function loadFlatFloor() {
  clearTileMap();
  const tiles = new Uint8Array(CHUNK_SIZE * CHUNK_SIZE);
  tiles.fill(TILE_FLOOR);
  loadChunk(0, 0, tiles);
}

function makeEntity(world, x, y, hp, faction, identity = "") {
  const id = world.create();
  world.add(id, Position, { x, y });
  world.add(id, Vitality, { maxHp: hp, hp });
  if (faction) world.add(id, Faction, { key: faction });
  if (identity) world.add(id, NamedIdentity, { name: identity, identity });
  return id;
}

Deno.test("fear: applies timed fear effect to targeted hostile", () => {
  loadFlatFloor();
  const world = new World({ seed: 21 });
  const events = [];
  world.on(FearSpellCast, (event) => events.push(event));

  const caster = makeEntity(world, 2, 2, 20, "player", "player");
  const target = makeEntity(world, 6, 2, 20, "enemy", "goblin");

  runSpellScript(world, caster, SPELL, { targetId: target });

  const ae = world.get(target, ActiveEffects);
  const fear = ae?.effects?.find((effect) => effect.key === "fear");
  assert(fear, "target should have fear effect");
  assert(fear.turnsLeft >= 4, "fear should last at least the base duration");
  assertEquals(fear.sourceId, caster);
  assertEquals(events.length, 1);
  assertEquals(events[0].targetId, target);
  assertEquals(events[0].fizzle, false);
  assertEquals(events[0].missed, false);
  assertEquals(events[0].projectileDelay, 0.4);
});

Deno.test("aiChaseSystem: feared monster flees away from target", () => {
  const world = new World({ seed: 22 });

  const player = world.create();
  world.add(player, Player);
  world.add(player, Position, { x: 5, y: 5 });
  world.add(player, NamedIdentity, { name: "Hero", identity: "player" });

  const goblin = world.create();
  world.add(goblin, Position, { x: 8, y: 5 });
  world.add(goblin, NamedIdentity, { name: "Goblin", identity: "goblin" });
  world.add(goblin, Faction, { key: "enemy" });
  world.add(goblin, ActiveEffects, {
    effects: [{ key: "fear", turnsLeft: 4, potency: 1, stacks: 1, sourceId: player }],
  });
  world.add(goblin, AggroState, {
    alertLevel: AGGRO_LEVELS.hunting,
    lastKnownX: 5,
    lastKnownY: 5,
    searchTurnsLeft: SEARCH_TURNS_HUNTING_GRACE,
    retreating: false,
  });

  aiChaseSystem(world);

  const intent = world.get(goblin, MoveIntent);
  assert(intent, "feared monster should get a flee MoveIntent");
  assertEquals(intent.dx, 1);
  assertEquals(intent.dy, 0);
});

  const actorFaction = String(world.get(actor, Faction)?.key || 'player');
  const MAX_R = Math.max(1, Number(spell.range || 8));
  const isBlocked = createLOSBlocker(world);
  const d2 = (x0, y0, x1, y1) => { const dx = x1 - x0, dy = y1 - y0; return dx * dx + dy * dy; };

  let targetId = Number(intent?.targetId || 0) | 0;
  let tpos = targetId ? /** @type any */ (world.get(targetId, Position)) : null;

  if (!targetId || !tpos) {
    /** @type {Array<{id:number,x:number,y:number,dist2:number}>} */
    const candidates = [];
    for (const [id, p] of world.query(Position)) {
      if (id === actor) continue;
      const fac = /** @type any */ (world.get(id, Faction));
      if (!fac || !areFactionsHostile(actorFaction, fac.key)) continue;
      const vit = /** @type any */ (world.get(id, Vitality));
      if (!vit || (vit.hp | 0) <= 0) continue;
      const dist2v = d2(apos.x, apos.y, p.x, p.y);
      if (dist2v <= MAX_R * MAX_R) candidates.push({ id, x: p.x, y: p.y, dist2: dist2v });
    }
    candidates.sort((a, b) => a.dist2 - b.dist2);
    let found = null;
    for (const c of candidates) {
      if (hasSpellLineOfSight(world, {
        sourceId: actor,
        targetId: c.id,
        sourcePos: apos,
        targetPos: c,
        range: MAX_R,
        isBlocked,
      })) { found = c; break; }
    }
    if (!found) {
      world.emit(new FearSpellCast({
        actor,
        targetId: actor,
        from: { x: apos.x, y: apos.y },
        at: { x: apos.x, y: apos.y },
        fizzle: true,
        reason: 'no_target',
      }));
      return;
    }
    targetId = found.id;
    tpos = { x: found.x, y: found.y };
  }

  const vit = /** @type any */ (world.get(targetId, Vitality));
  if (!vit || (vit.hp | 0) <= 0) {
    world.emit(new FearSpellCast({
      actor,
      targetId,
      from: { x: apos.x, y: apos.y },
      at: { x: tpos?.x ?? apos.x, y: tpos?.y ?? apos.y },
      fizzle: true,
      reason: 'invalid_target',
    }));
    return;
  }

  if (!hasSpellLineOfSight(world, {
    sourceId: actor,
    targetId,
    sourcePos: apos,
    targetPos: tpos,
    range: MAX_R,
    isBlocked,
  })) {
    world.emit(new FearSpellCast({
      actor,
      targetId,
      from: { x: apos.x, y: apos.y },
      at: { x: tpos.x, y: tpos.y },
      fizzle: true,
      reason: 'no_los',
    }));
    return;
  }

  const dist = chebyshev(apos, tpos);
  if (dist > MAX_R) {
    world.emit(new FearSpellCast({
      actor,
      targetId,
      from: { x: apos.x, y: apos.y },
      at: { x: tpos.x, y: tpos.y },
      fizzle: true,
      reason: 'out_of_range',
    }));
    return;
  }

  const fearFrom = { x: apos.x, y: apos.y };
  const fearAt = { x: tpos.x, y: tpos.y };
  const travelDist = Math.hypot(fearAt.x - fearFrom.x, fearAt.y - fearFrom.y) || 1;
  const projectileDelay = Math.max(0.08, Math.min(0.7, travelDist / 10));
  const hitChancePct = getSpellHitChancePct(world, actor, targetId);
  if (!rollSpellHit(world, actor, targetId, spell)) {
    emitSpellMiss(world, actor, targetId, spell, {
      cause: 'spell:fear',
      hitChancePct,
      at: fearAt,
    });
    world.emit(new FearSpellCast({
      actor,
      targetId,
      from: fearFrom,
      at: fearAt,
      missed: true,
      missTo: resolveMissTo(world, actor, targetId, fearFrom, fearAt, 'spell:fear', 0xfea2),
      projectileDelay,
    }));
    return;
  }

  const intBonus = getSpellIntelligenceBonus(world, actor);
  const duration = Math.min(7, 4 + Math.floor(intBonus / 6));
  const fearEffect = {
    key: 'fear',
    turnsLeft: duration,
    potency: 1,
    stacks: 1,
    startedAtTurn: world.step,
    sourceId: actor,
  };
  const ae = /** @type any */ (world.get(targetId, ActiveEffects));
  if (ae && Array.isArray(ae.effects)) {
    upsertTimedEffect(ae.effects, fearEffect);
  } else {
    try { world.add(targetId, ActiveEffects, { effects: [fearEffect] }); } catch {}
  }

  world.emit(new FearSpellCast({
    actor,
    targetId,
    from: fearFrom,
    at: fearAt,
    projectileDelay,
    duration,
  }));
};

